INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('cc9c9ffc-c0f9-5d62-a337-f99c63cda42a', NULL, 'SkyUI Team', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '12604', 'SkyUI', 'Elegant, PC-friendly interface mod with many advanced features. Upgraded with full support for all modern game versions.', 'User Interface', 26275170, 506706, TRUE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('c9729a61-7a6f-5bc2-a357-1fc71c8f0278', NULL, 'The Unofficial Patch Project Team', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '266', 'Unofficial Skyrim Special Edition Patch - USSEP', 'A comprehensive bugfixing mod for The Elder Scrolls V: Skyrim - Special Edition. The goal of the Unofficial Skyrim Special Edition Patch (aka USSEP) is to eventually fix every bug with Skyrim Special Edition not officially resolved by the developers to the limits of the Creation Kit and community-developed tools, in one easy-to-install package.', 'Bug Fixes', 28255837, 480353, TRUE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('b4b8618a-c1a9-56cf-85be-ad39158054fb', NULL, 'meh321', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '32444', 'Address Library for SKSE Plugins', 'Database to make SKSE DLL plugins version independent easily.', 'Modders Resources', 26609153, 283901, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('6158c847-4daa-5903-b590-92aa19bc04df', NULL, 'aers - Nukem - Ryan', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '17230', 'SSE Engine Fixes (skse64 plugin)', 'skse64 plugin to fix various issues with the Skyrim Special Edition engine.', 'Bug Fixes', 29783537, 188103, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('17945fae-bcf4-503e-9f2e-a7fa52345ae2', NULL, 'Brumbek', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '659', 'Static Mesh Improvement Mod - SMIM', 'A massive project to greatly improve the appearance of countless static 3D models in Skyrim. Basically, this is my attempt to make the Skyrim architecture, clutter, furniture, and landscaping much nicer.', 'Models and Textures', 17401745, 273848, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('37fca199-219c-5089-a46c-b3c1554d5d73', NULL, 'Arthmoor', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '272', 'Alternate Start - Live Another Life - SSE', 'Live Another Life provides an alternative means to start the game for those who do not wish to go through the lengthy intro sequence at Helgen.', 'Gameplay', 11758238, 240284, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('2cbbc736-caa9-5639-9f52-d8049da88173', NULL, 'Expired', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '19080', 'RaceMenu', 'Complete overhaul to the character creation menu including new customization features such as multiple RGBA warpaints, body paints, hand paint, and foot paints. (Requires SKSE)', 'User Interface', 23012510, 270366, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('fbdbaca2-0a6e-5ff2-85b7-8333d24863ee', NULL, 'Enai Siaion', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '1137', 'Ordinator - Perks of Skyrim', 'Ordinator overhauls the perk trees of Skyrim to increase the depth and fun of character building. It is highly compatible with other mods and uses lightweight and clean scripting.', 'Overhauls', 16415223, 190798, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('b638a78f-d410-5768-abc4-3e266301eabe', NULL, 'Enai Siaion', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '1090', 'Apocalypse - Magic of Skyrim', 'Apocalypse is the most popular Skyrim spell pack, adding 175 new spells that are unique, balanced, lore friendly, use high quality custom visuals and blend seamlessly into the vanilla magic system. Also includes scrolls and staves for the new spells.', 'Magic - Spells & Enchantments', 16142778, 157963, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('282f6a4a-9f90-5863-a2e1-ddfe23da53ee', NULL, 'Chesko', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '667', 'Campfire - Complete Camping System (Supports Skyrim VR)', 'Campfire is the most feature-rich stand-alone camping mod for The Elder Scrolls V: Skyrim, created from Frostfall''s immersive and detailed camping system. Campfire is also a modder''s framework, allowing anyone to create their own unique camping equipment.', 'NPC', 5616934, 78896, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('eeb9d71d-6249-524a-970c-5fb996a8a0d4', NULL, 'Chesko', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '671', 'Frostfall - Hypothermia Camping Survival', 'Frostfall is a survival-style mod that adds cold weather survival gameplay elements to Skyrim.', 'NPC', 1916257, 45371, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('595b327d-57c6-54a3-85c4-50085c16be60', NULL, 'exiledviper meh321', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '13048', 'PapyrusUtil SE - Modders Scripting Utility Functions', 'An SKSE plugin adding several new scripts with native functions that provide various conveniences related to data storage and other misc functions to the scripter/modder.', 'Modders Resources', 16953256, 165123, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('a0aa646a-6afd-59aa-8e6a-cafd71391741', NULL, 'ecirbaf', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '1429', 'Better Dialogue Controls', 'Ever pick the wrong item in a dialogue with a NPC? This mod aims to fix some annoyances with the way keyboard and mouse selection works in the dialogue interface.', 'User Interface', 4934197, 91161, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('0b838ce6-b4d9-53d5-9fd3-148b255c8b64', NULL, 'IcePenguin', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '5804', 'A Quality World Map', 'Provides a new set of highly-detailed 3D or paper world map textures, complete with roads! Also adds a detailed Solsteim map.', 'User Interface', 11901249, 253101, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('a07d0dce-73d5-5794-b23a-fda818981cc6', NULL, 'Parapets', '892b18d7-23e7-5b09-88aa-c40b93e95d27', '53000', 'MCM Helper', 'Simplifies the creation of Mod Configuration Menus and extends them with powerful new features, such as persistent INI settings and hotkey registration. Mod authors will be able to write simpler, cleaner Papyrus scripts for their configs. Players will be able to spend less time in menus.', 'Utilities', 12717500, 89356, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('d609cb65-494d-58dd-9dc9-91894c63e4f6', NULL, 'The Unofficial Patch Project Team', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '4598', 'Unofficial Fallout 4 Patch - UFO4P', 'A comprehensive bugfixing mod for Fallout 4. The goal of the Unofficial Fallout 4 Patch (aka UFO4P) is to eventually fix every bug with Fallout 4 not officially resolved by the developers to the limits of the Creation Kit and community-developed tools, in one easy-to-install package.', 'Bug Fixes', 10940779, 214769, TRUE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('dc9b2af6-64a9-501a-a46b-b8cb99b3c929', NULL, 'F4SE Team', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '42147', 'Fallout 4 Script Extender (F4SE)', 'The Fallout 4 Script Extender, or F4SE for short, is a modder''s resource that expands the scripting capabilities of Fallout 4. It does so without modifying the executable files on disk, so there are no permanent side effects.', 'Utilities', 8516404, 101594, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('1367beba-176f-576a-9e2e-3b74ca0355d3', NULL, 'reg2k - Neanka - shadowslasher410', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '21497', 'Mod Configuration Menu', 'The Mod Configuration Menu is a settings page for mods! It provides a central location for mod configuration, accessible via the Pause menu.', 'User Interface', 10586126, 162378, TRUE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('6d0b5c27-e9e8-5127-8e8b-6fd855beded0', NULL, 'Gambit77 - Thirdstorm - Valdacil', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '6091', 'Armor and Weapon Keywords Community Resource (AWKCR)', 'This is a master file to create a standardize framework for armor so that modders can create and modify armor (like Armorsmith) while making edits compatible with mods that adjust dynamic item naming (like Valdacil''s Item Sorting). Also adds a standardized set of crafting menu categories for armor/clothing/weapons and adds two workbenches for m', 'Modders Resources and Tutorials', 12217884, 246030, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('e6633ff5-572c-5261-afa7-1c16c3d3b295', NULL, 'Gambit77', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '2228', 'Armorsmith Extended', 'This mod does so much awesome stuff that the description doesn''t come anywhere close to fitting here.', 'Armour', 11812951, 214091, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('d715893d-e533-5fce-9492-11e9232b90d7', NULL, 'TheLich', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '9424', 'Place Everywhere', 'Place/build objects in settlements everywhere you want, change objects whatever you like. No more RED!', 'Player Settlement', 7110101, 120071, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('e07ac24e-3247-52f0-b9be-4320e6973c53', NULL, 'Cirosan and shadwar', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '1235', 'Full Dialogue Interface (NewDialog English and CN-DE-ES-FR-IT-JA-PL-PTBR-RU translations)', 'Makes the game display the full lines of what your character is going to say in conversation, instead of just a paraphrase. It also revamps the interface so that the game will now display dialogue options in a list and use the number keys/face buttons for input, depending on your control scheme. Supports both keyboard and gamepad.', 'User Interface', 7270088, 179969, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('553133a8-4ec7-5215-882f-f44de84fc170', NULL, 'TinyManticore', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '18946', 'Start Me Up - Alternate Start and Dialogue Overhaul', 'Provides Alternate start, Quick start, Normal start options. When you use one of the alternate start paths, there are over 800 dialogue edits, with voice and lip sync, so your character is no longer the mother/father of Shaun (or even a Vault Dweller, if you want). Great for role players.', 'Gameplay', 4421694, 69011, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('bcf361ad-2e4c-50e0-8203-4217c840e32c', NULL, 'kinggath', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '35004', 'Workshop Framework', 'Framework to open up the settlement system to editing by the community.For Players: New controls and faster, more stable workshop scripts.For Modders: Add new resource types, override settings, and generally change the way settlements work dynamically.', 'Player Settlement', 6160311, 59943, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
