INSERT INTO mods (mod_id, author_id, nexus_author, game_id, nexus_mod_id, name, summary, category, download_count, endorsement_count, is_featured, rating_avg, rating_count, embedding) VALUES ('5a2bd525-18f3-5c16-b41c-bb860a0c24ab', NULL, 'fadingsignal', '8b9fac3f-22b2-5636-9eb0-252a35c93bde', '4472', 'True Storms - Wasteland Edition (Thunder-Rain-Weather Redone)', 'One of the highest ranked Skyrim mods comes to Fallout 4 with even more features than ever! True Storms: Wasteland Edition is a complete overhaul to the storm systems in Fallout 4. Heavy rains, dust storms, radiation rains. New unique weathers, sound effects, particle effects, textures and more including configurable ghoul hordes during radstorms', 'Weather and Lighting', 8300464, 158563, FALSE, 0, 0, NULL) ON CONFLICT (game_id, nexus_mod_id) DO NOTHING;
