INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('f0ee9618-fc9f-5e10-9896-b79cf561ad75', '1367beba-176f-576a-9e2e-3b74ca0355d3', '1.22b', '115640', 'For Fallout 4 game version 1.10.50.   What''s new in v1.22? - Support for game version v1.10.50.   For a full changelog, check the Changes tab. To update, simply replace and overwrite the old files. The MCM is stateless and can be safely updated at any time.', '{}'::TEXT[], FALSE, to_timestamp(1512117641)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('4f1a0cbf-897b-5750-bef2-5c551c6b64b1', '1367beba-176f-576a-9e2e-3b74ca0355d3', '1.22', '115637', '', '{}'::TEXT[], FALSE, to_timestamp(1512113120)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('43b6bd35-b5fa-56d8-9701-11e7f5e91e19', '1367beba-176f-576a-9e2e-3b74ca0355d3', '1.21', '114132', 'For Fallout 4 game version 1.10.40.   What&#39;s new in v1.21? - Support for game version v1.10.40.   For a full changelog, check the Changes tab. To update, simply replace and overwrite the old files. The MCM is stateless and can be safely updated at any time.', '{}'::TEXT[], FALSE, to_timestamp(1510396155)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('3e02c712-c52d-50df-9317-264b817e4dc9', '1367beba-176f-576a-9e2e-3b74ca0355d3', '1.20', '111561', 'For Fallout 4 game version 1.10.26.   What&#39;s new in v1.20? - Added text input controls. - Basic support for re-ordering config menus.   For a full changelog, check the Changes tab. To update, simply replace and overwrite the old files. The MCM is stateless and can be safely updated at any time.', '{}'::TEXT[], FALSE, to_timestamp(1507740274)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('8c72fd29-a404-5a7c-85ea-1f2751147b3b', '1367beba-176f-576a-9e2e-3b74ca0355d3', '1.12', '110147', 'For Fallout 4 game version 1.10.20.   Install the main file first, then install this patch, allowing the overwrite of the MCM F4SE plugin.', '{}'::TEXT[], FALSE, to_timestamp(1506197396)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('d05577c1-24ad-5c54-a07d-0c509995904d', '1367beba-176f-576a-9e2e-3b74ca0355d3', '1.11', '109957', 'For Fallout 4 game version 1.10.20.   What&#39;s new in v1.10 / v1.11? - Support for assigning hotkeys to mouse buttons. (Mouse3-Mouse8). - Added ability to reposition MOD CONFIG in the Pause menu. - Two new controls and one new value source option for modders. - Fixed an issue with the left panel scrollbar not appearing (v1.11) - Modders can now add additional pages to another mod&#39;s MCM menu (v1.11)   For a full changelog, check the Changes tab. To update, simply replace and overwrite the old files. The MCM is stateless and can be safely updated at any time.', '{}'::TEXT[], FALSE, to_timestamp(1505977303)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('abdb887a-0d48-5733-a90d-f0efc5b09d55', '1367beba-176f-576a-9e2e-3b74ca0355d3', '1.1', '109323', 'For Fallout 4 game version 1.9.4', '{}'::TEXT[], FALSE, to_timestamp(1505409008)) ON CONFLICT (mod_id, semver) DO NOTHING;
