INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('32bd457a-e008-5b7b-8232-b939a22b12a9', '6d0b5c27-e9e8-5127-8e8b-6fd855beded0', '2.2.1', '54309', 'Standardize framework for armor so that modders can create and modify armor while making edits compatible with mods that adjust dynamic item naming. Includes Synth Armor No Misc Fix - compatible with everything, so don&#39;t use both. Includes updates from UFO4P. Contains a unified set of armor/clothing/weapons crafting menu category keywords and two new custom crafting stations, the Armorsmith and Weaponsmith workbenches. As of v1.8, this contains a standard ma keyword for use by weapon modders, a set of OMODs for damage upgrades for blade weapons, and dn keywords for Tactical Light, Laser Sight, & Tactical Light/Laser Sight combo OMODs. Adds sorting keywords for weapon calibers and added missing HasConverted(Caliber) keywords for the calibers that weren&#39;t in vanilla, to make it easier for weapon modders to set up their gun mods for dynamic sorting.', '{}'::TEXT[], FALSE, to_timestamp(1463674817)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('e5d6af30-b41c-5451-88f8-fe75872b4c4b', '6d0b5c27-e9e8-5127-8e8b-6fd855beded0', '2.2.0', '54226', 'Standardize framework for armor so that modders can create and modify armor while making edits compatible with mods that adjust dynamic item naming. Includes Synth Armor No Misc Fix - compatible with everything, so don&#39;t use both. Includes updates from UFO4P. Contains a unified set of armor/clothing/weapons crafting menu category keywords and two new custom crafting stations, the Armorsmith and Weaponsmith workbenches. As of v1.8, this contains a standard ma keyword for use by weapon modders, a set of OMODs for damage upgrades for blade weapons, and dn keywords for Tactical Light, Laser Sight, & Tactical Light/Laser Sight combo OMODs. Adds sorting keywords for weapon calibers and added missing HasConverted(Caliber) keywords for the calibers that weren&#39;t in vanilla, to make it easier for weapon modders to set up their gun mods for dynamic sorting.', '{}'::TEXT[], FALSE, to_timestamp(1463636864)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('79c53ccd-c28d-5126-b2a4-33e04f0c47bc', '6d0b5c27-e9e8-5127-8e8b-6fd855beded0', '2.1.1', '50262', 'Standardize framework for armor so that modders can create and modify armor while making edits compatible with mods that adjust dynamic item naming. Includes Synth Armor No Misc Fix - compatible with everything, so don&#39;t use both. Includes updates from UFO4P. Contains a unified set of armor/clothing/weapons crafting menu category keywords and two new custom crafting stations, the Armorsmith and Weaponsmith workbenches. As of v1.8, this contains a standard ma keyword for use by weapon modders, a set of OMODs for damage upgrades for blade weapons, and dn keywords for Tactical Light, Laser Sight, & Tactical Light/Laser Sight combo OMODs. Adds sorting keywords for weapon calibers and added missing HasConverted(Caliber) keywords for the calibers that weren&#39;t in vanilla, to make it easier for weapon modders to set up their gun mods for dynamic sorting.', '{}'::TEXT[], FALSE, to_timestamp(1462053109)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('09362c52-c313-5f92-8c01-3ceca08144f2', '6d0b5c27-e9e8-5127-8e8b-6fd855beded0', '2.1.0', '49857', 'Standardize framework for armor so that modders can create and modify armor while making edits compatible with mods that adjust dynamic item naming. Includes Synth Armor No Misc Fix - compatible with everything, so don&#39;t use both. Includes updates from UFO4P. Contains a unified set of armor/clothing/weapons crafting menu category keywords and two new custom crafting stations, the Armorsmith and Weaponsmith workbenches. As of v1.8, this contains a standard ma keyword for use by weapon modders, a set of OMODs for damage upgrades for blade weapons, and dn keywords for Tactical Light, Laser Sight, & Tactical Light/Laser Sight combo OMODs. Adds sorting keywords for weapon calibers and added missing HasConverted(Caliber) keywords for the calibers that weren&#39;t in vanilla, to make it easier for weapon modders to set up their gun mods for dynamic sorting.', '{}'::TEXT[], FALSE, to_timestamp(1461906179)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('79b132fe-0b66-5614-a22f-f6535e658f20', '6d0b5c27-e9e8-5127-8e8b-6fd855beded0', '2.03', '48325', 'Standardize framework for armor so that modders can create and modify armor while making edits compatible with mods that adjust dynamic item naming. Also contains Synth Armor No Misc Fix - compatible with everything , so don&#39;t use both. Also now contains a unified set of armor/clothing/weapons crafting menu category keywords and two new custom crafting stations, the Armorsmith and Weaponsmith workbenches. As of v1.8, this contains a standard ma keyword for use by weapon modders, a set of OMODs for damage upgrades for blade weapons, and dn keywords for Tactical Light, Laser Sight, & Tactical Light/Laser Sight combo OMODs. The release of Weaponsmith Extended will demonstrate how to replace ma keyword filtering for mod weapons with a GetEquipped condition. This was set up so that people can use lots of mod weapons without using up a bunch of the very limited amount of ma keywords that we have available before hitting the cap and causing the mod menu category formlist cap/ invisible robot bug. Also adds sorting keywords for weapon calibers and added missing HasConverted(Caliber) keywords for the calibers that weren&#39;t in vanilla, to make it easier for weapon modders to set up their gun mods for dynamic sorting.', '{}'::TEXT[], FALSE, to_timestamp(1461068455)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('692023b7-f31f-53c7-9bd2-62f7fe1dc439', '6d0b5c27-e9e8-5127-8e8b-6fd855beded0', '2.02', '48318', 'Standardize framework for armor so that modders can create and modify armor while making edits compatible with mods that adjust dynamic item naming. Also contains Synth Armor No Misc Fix - compatible with everything , so don&#39;t use both. Also now contains a unified set of armor/clothing/weapons crafting menu category keywords and two new custom crafting stations, the Armorsmith and Weaponsmith workbenches. As of v1.8, this contains a standard ma keyword for use by weapon modders, a set of OMODs for damage upgrades for blade weapons, and dn keywords for Tactical Light, Laser Sight, & Tactical Light/Laser Sight combo OMODs. The release of Weaponsmith Extended will demonstrate how to replace ma keyword filtering for mod weapons with a GetEquipped condition. This was set up so that people can use lots of mod weapons without using up a bunch of the very limited amount of ma keywords that we have available before hitting the cap and causing the mod menu category formlist cap/ invisible robot bug. Also adds sorting keywords for weapon calibers and added missing HasConverted(Caliber) keywords for the calibers that weren&#39;t in vanilla, to make it easier for weapon modders to set up their gun mods for dynamic sorting.', '{}'::TEXT[], FALSE, to_timestamp(1461066169)) ON CONFLICT (mod_id, semver) DO NOTHING;
