INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('1c45a1b6-5e4e-5fea-96d8-d2a8f8c008dd', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '3.2', '80757', 'NOTE: MERGED PLUGINS HAVE DIFFERENT FORMIDS THAN THE ORIGINAL PLUGINS. SALVAGE ANY MODS OFF OUTFITS BEFORE INSTALLING THIS. Fallout 4 B-90 ARMOR by L0rd0fWar v0.7 , The Rebel by L0rd0fWar v0.3 , Scavenged NCR Armor by L0rd0fWar v0.4 , Rebel Camouflage Pack by pr0c v0.22 , The Rebel Tex-Edits All-In-One Standalone Crafting by Griffin aka RafftheSweetling - AmaekilShath v.02 , and The Rebel Flannels by Oh Deer - Gambit77 v1.1 are required to use this file.', '{}'::TEXT[], FALSE, to_timestamp(1478210286)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('fada6ada-78ea-5c63-8135-e07f5f038f5e', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '3.12', '74674', 'Requires Armor and Weapon Keywords Community Resource (AWKCR) v3.0.4+ This is just a patch, AE v3.12 is still required as well.', '{}'::TEXT[], FALSE, to_timestamp(1473955341)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('1a957c9f-ea5a-5469-a995-b1e1cba1f015', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '3.11', '72111', 'REQUIRES Armor & Weapon Keywords Community Resource (AWKCR) v3.0 . Compatible with Valdacil&#39;s Item Sorting . Every outfit can now be worn under armor pieces, renamed, and I completely redid the entire clothing modding system from scratch. There are now 8 different types of mods: lining mods, outfit add-on mods, headgear add-on mods, glove mods, eyewear mods, therm optics booster mods, carry weight base effect mods, & carry weight modifier mods. Adds new craftable outfits, headgear, gloves, scarves, custom Dogmeat armors, Helmets/Hats With Hair, Under Helmet Flight Cap & BOS/Sack Hoods, Nudifying Rings, Invisible Therm Optics Combat Armor, Pistol & Revolver Harnesses, Katana Belt, a working jetpack, and lots of wearable weapons. TAKE NOTICE: NCR Ranger Sequoia by Rakul aka GrindOne assets are needed if you want to mod the revolver harness or 44 pistol on hip into the Ranger Sequoia.', '{}'::TEXT[], FALSE, to_timestamp(1472697516)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('80bd191b-51f4-5438-abfe-73b805da8754', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '3.1', '71928', 'Requires Armor and Weapon Keywords Community Resource (AWKCR) v3.0 This is just a patch, AE v3.1 is still required as well.', '{}'::TEXT[], FALSE, to_timestamp(1472637688)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('e9d91c6b-9a55-5868-bb11-218295a50878', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '3.02', '71033', 'NOTE: MERGED PLUGINS HAVE DIFFERENT FORMIDS THAN THE ORIGINAL PLUGINS. SALVAGE ANY MODS OFF OUTFITS BEFORE INSTALLING THIS. Dogmeat&#39;s Backpack by Higeyosi v2.0 , Field Scribe Backpack by jet4571 v1.07 , Hubris Comics Shoulder Bags by TotalMeltdown v1.5d , Survivalist Go-Bags by Tookie Jones v1.2 , Wearable Backpacks and Pouches by Aldebaran90 and Stndmunki v1.4b , Wearable Camo Backpacks by Aldebaran90 and Voivre v1.0 , and Wearable Postman Shoulder Bag or Backpack by Eferas v1.7 are required to use this file.', '{}'::TEXT[], FALSE, to_timestamp(1472030982)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('65ee55d5-53ce-5d8e-87be-333ab7abb646', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '3.01', '49293', 'This is an AE replacer plugin for Commonwealth Scavvers - AWKCR by Moore v4.0 which is required to use this file.', '{}'::TEXT[], FALSE, to_timestamp(1461692535)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('455783cb-19ff-5d21-8622-e5e515c0895d', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '3.0', '48359', 'REQUIRES Armor & Weapon Keywords Community Resource (AWKCR) v2.03 . Compatible with Valdacil&#39;s Item Sorting . Every outfit can now be worn under armor pieces, renamed, and I completely redid the entire clothing modding system from scratch. There are now 8 different types of mods: lining mods, outfit add-on mods, headgear add-on mods, glove mods, eyewear mods, therm optics booster mods, carry weight base effect mods, & carry weight modifier mods. Adds new craftable outfits, headgear, gloves, scarves, custom Dogmeat armors, Helmets/Hats With Hair, Under Helmet Flight Cap & BOS/Sack Hoods, Nudifying Rings, Invisible Therm Optics Combat Armor, Pistol & Revolver Harnesses, Katana Belt, a working jetpack, and lots of wearable weapons. TAKE NOTICE: Insanity&#39;s Celtic Katana assets are required for the Katana Belt. Mysterious Magnum by Nonow and Robtest and NCR Ranger Sequoia by Rakul aka GrindOne assets are needed if you want to mod the revolver harness or 44 pistol on hip into either of these two guns.', '{}'::TEXT[], FALSE, to_timestamp(1461077881)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('72159c21-48d1-584c-b9f8-ce7d41aeaaec', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.91', '47214', 'NOTE: MERGED PLUGINS HAVE DIFFERENT FORMIDS THAN THE ORIGINAL PLUGINS. SALVAGE ANY MODS OFF OUTFITS BEFORE INSTALLING THIS. Balaclava and Masks (Sack Remodel n Retex) by cat_woman1989 v1.6 , Clean Drifter Outfits by cat_woman1989 v1.4 , Commonwealth Camo by cat_woman1989 v1.1 , Dark Drifter Outfits by cat_woman1989 v1.8.1 , Faction Field Outfits by cat_woman1989 v1.5 , and Helmetless Hazmat Suit by cat_woman1989 v1.8 are required to use this file.', '{}'::TEXT[], FALSE, to_timestamp(1460406078)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('29fbd409-5b74-5b50-8c4d-fc6eace54cda', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.9', '45206', 'This just has the changes in it. It&#39;s useful for making a new AE patch if Lagrie&#39;s Helmet Collection STANDALONE by Lagrie gets updated.', '{}'::TEXT[], FALSE, to_timestamp(1459222802)) ON CONFLICT (mod_id, semver) DO NOTHING;
