INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('79346732-82fe-51b8-84dd-99db7c790835', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.81', '44914', 'This is a WSE-AE-VIS replacer plugin for Raider Overhaul WIP v9.2 by MadMAX713 .', '{}'::TEXT[], FALSE, to_timestamp(1459104159)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('e485fadb-4e1e-5268-bbf5-a7e21504696e', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.8', '44370', 'WARNING: UNEQUIP SATCHELS BEFORE YOU INSTALL THIS OR YOU CAN GET A CARRY WEIGHT BONUS STUCK ON YOUR PLAYER. Elianora - Eli&#39;s Armour Collection Remade v3.4 , Apocalypse Accessories - Glasses - Scarves - Bags v1.1 , Eli&#39;s Rugged Outfits - CBBE v1.0 & Apocalypse Attire - CBBE v1.1 are required files for the Armorsmith Elianora Extended file. This version has perk crafting requirements for the outfits from Rugged Outfits.', '{}'::TEXT[], FALSE, to_timestamp(1458850606)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('6fcfde3e-ddc3-52bc-a5af-b9ba6b94b3d1', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.75', '43744', 'WARNING: UNEQUIP SATCHELS BEFORE YOU INSTALL THIS OR YOU CAN GET A CARRY WEIGHT BONUS STUCK ON YOUR PLAYER. Elianora - Eli&#39;s Armour Collection Remade v3.4 , Apocalypse Accessories - Glasses - Scarves - Bags v1.1 , Eli&#39;s Rugged Outfits - CBBE v1.0 & Apocalypse Attire - CBBE v1.1 are required files for the Armorsmith Elianora Extended file. This version has perk crafting requirements for the outfits from Rugged Outfits.', '{}'::TEXT[], FALSE, to_timestamp(1458515965)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('8aa1763f-428b-585b-92b7-d3cc946f0427', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.71', '37213', 'Deserter X - Courser X-92 Power Suit CBBE and PipBoy v1.51 , guffeh - Kerrigan Bodysuit v1.5 (no color changing plugin, and I&#39;m using the non-AE plugins if that matters) , vasstek - Nanosuit 4.1 Standalone Full package FOMOD v4.1 (suit and helmet plugins) & NanoArmor 2.0 StandAlone by vasstek( BodySlide compatible - 4 different skins - glow types ) v2.0 , LOrdOfWar - Fallout 4 B-90 ARMOR v0.5 , & Crishark - Stealth Suit v6.0 are required files for the Armorsmith Prototypes Extended file. The outfits are crafted in the Cybertech and Therm Optics menu, and the Nano Armor is crafted in the Armor menu in the Armorsmith workbench. In addition to the usual AE modding I&#39;ve enabled the therm optics mods on these outfits. The B-90 jetpacks are now functional. The Nanosuit is now the male model for the Courser X-92 Power Suit & Kerrigan Bodysuit instead of them not having a male body model. NOTICE: THIS WILL ASK YOU TO OVERWRITE PLUGINS FROM THE REQUIRED FILES. CHOOSE YES. THESE REPLACER PLUGINS HAVE HAD THE UNUSED MENU CATEGORY KEYWORDS DELETED FROM THE PLUGIN TO HELP AVOID THE CRAFTING MENU KEYWORD FORMLIST CAP BUG. ALSO I RECOMMEND NOT USING THE KERRIGAN COLOR CHANGING PLUGIN AT THIS TIME. DON&#39;T GET ME WRONG, I THINK USING THE MOD SYSTEM TO CUSTOMIZE CLOTHING APPEARANCE IS VERY COOL, BUT WITH THE MOD MENU CATEGORY KEYWORD FORMLIST CAP BUG THAT&#39;S POPPED UP I DON&#39;T RECOMMEND USING THE VERY LIMITED AMOUNT OF MA KEYWORDS ON VISUAL MODIFICATIONS AT THIS TIME.', '{}'::TEXT[], FALSE, to_timestamp(1455056486)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('24cebe20-eaa5-5e2d-af7c-8d16bd50dc0e', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.7', '36341', 'Compatible with Valdacil&#39;s Item Sorting . Every outfit can now be worn under armor pieces, renamed, and I completely redid the entire clothing modding system from scratch. There are now 5 different types of mods: Lining mods, outfit add-on mods, headgear add-on mods, Glove mods, and eyewear mods. Adds new craftable outfits, headgear, gloves, scarves, custom Dogmeat armors, Helmets/Hats With Hair, Under Helmet Flight Cap & BOS/Sack Hoods, Nudifying Rings, Invisible Therm Optics Combat Armor, Pistol Harness, Katana Belt, Sniper Rifle on back, & a working jetpack. Contains Armor & Weapon Keywords Community Resource (AWKCR) v1.71 . TAKE NOTICE: Insanity&#39;s Celtic Katana assets are required for the new Katana Belt.', '{}'::TEXT[], FALSE, to_timestamp(1454640669)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('67daa933-41dc-54d4-beb9-589958ce58f7', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.61', '36062', 'Elianora - Eli&#39;s Armour Collection Remade v3.4 is a required file for the Armorsmith Elianora Extended file.', '{}'::TEXT[], FALSE, to_timestamp(1454524719)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('971a841d-7c69-525b-8d47-75c254915a3d', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.6', '32600', 'nsk13 - Chem I Care Outfit v1.2 , Commonwealth Mini Dresses Vanilla-CBBE v1.2 , Commonwealth Shorts Vanilla-CBBE v1.2 , Vault Girl Shorts Vanilla-CBBE v1.2 , & Adventurer Outfit v1.0 are required files for the Armorsmith DeserterX Extended file.', '{}'::TEXT[], FALSE, to_timestamp(1453175561)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('9091631e-5ba2-51ad-9ffa-9794345639f3', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.51', '31431', 'Compatible with Valdacil&#39;s Item Sorting . Every outfit can now be worn under armor pieces, renamed, and I completely redid the entire clothing modding system from scratch. There are now 5 different types of mods: Lining mods, outfit add-on mods, headgear add-on mods, Glove mods, and eyewear mods. Adds new craftable outfits, headgear, gloves, custom Dogmeat armors, Helmets/Hats With Hair, Under Helmet Flight Cap & BOS/Sack Hoods, Nudifying Rings, Invisible Therm Optics Combat Armor, Pistol Harness, Katana Belt, Sniper Rifle on back, & a working jetpack. Contains Armor Keywords Community Resource (AKCR) v1.55 . TAKE NOTICE: Insanity&#39;s Celtic Katana assets are required for the new Katana Belt.', '{}'::TEXT[], FALSE, to_timestamp(1452832251)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('0a8f8a3f-0e78-500c-b8c8-02ac6f18e7a5', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.5', '30340', 'cat_woman1989 - Helmetless Hazmat Suit v1.7 , Clean Drifter Outfit and Coat v1.4 , & Dark Drifter Outfit v1.7 and Dark Hats v1.1 are required files for the Armorsmith cat_woman1989 Extended file.', '{}'::TEXT[], FALSE, to_timestamp(1452543119)) ON CONFLICT (mod_id, semver) DO NOTHING;
