INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('60666be6-80db-585a-9fed-5d4b7cef8adf', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.4', '28073', 'Calyps - Daisy Nukes - Cutoff Jeans and much more - Craftable v1.2.8minis and Harness Wardrobe - Craftable Variants and Replacers v1.0.6b are both required files for the Armorsmith Calyps Extended File.', '{}'::TEXT[], FALSE, to_timestamp(1451935012)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('d0c43608-e6d3-5e2f-83a3-3eb0e16f6149', 'e6633ff5-572c-5261-afa7-1c16c3d3b295', '2.31', '26771', 'Wearable Travel Backpack by Aldebaran90 v1.3 , Wearable Camo Backpacks by Aldebaran90 and Voivre v1.0 , Wearable Postman Shoulder Bag or Backpack by Eferas v1.6 , & Hubris Comics Shoulder Bags by TotalMeltdown v1.5b are all required files for the Armorsmith Pact It Up Pack It In file. This file effects only slot 61 backpacks from WTB and WCB, and moves HCSB satchels to slot 61. So all packs tweaked by this file are now on slot 61 and they are craftable in the packs menu of the Armorsmith workbench. Adds keywords for VIS and LM. All packs received a scaling strength based carry weight boost. The small satchel is 2 X Strength, the shoulder bags are 6 X Strength, & the backpacks are 10 X Strength.', '{}'::TEXT[], FALSE, to_timestamp(1451689577)) ON CONFLICT (mod_id, semver) DO NOTHING;
