INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('402150dc-61a0-5d3f-bcee-40c5153f8139', 'e4b2fbc7-a2ab-5ce5-87cc-cd1cb5dbb46c', 'Beta.FUV88', '102079', 'Hopefully working version of Vault 88. Finally got it working (for me), no loose files or ini edits giving false positives. Please try it out and let me know if it works, or if it doesn&#39;t. MAKE SURE ALL LOOSE FILES FROM THE &#34;ALL DLC&#34; VERSION ARE REMOVED', '{}'::TEXT[], FALSE, to_timestamp(1498097698)) ON CONFLICT (mod_id, semver) DO NOTHING;
