INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('f40a24e4-1225-5cca-9b6a-ca747610db66', 'a144c7cd-5c8a-5852-abc8-63cbc5aa66d0', '1.1c', '63106', 'Adds BS items to Far Harbor Settlers, and adds Lever Rifle to settler lists. MORTAL VERSION. Use this or regular version. Not both. Please let me know of Bugs. Place after all other BS Files.', '{}'::TEXT[], FALSE, to_timestamp(1467251131)) ON CONFLICT (mod_id, semver) DO NOTHING;
INSERT INTO mod_versions (version_id, mod_id, semver, nexus_version_id, changelog, supported_game_versions, is_primary, uploaded_at) VALUES ('3524dca8-4879-5f20-a382-c15025abdcf0', 'a144c7cd-5c8a-5852-abc8-63cbc5aa66d0', '1.1', '57272', 'This is a BETA Far Harbor Patch. It adds the Lever Rifle to leveled lists and gives BS equipment to Far Harbor Settlers. PLEASE REPORT ANY BUGS. Must go after BS and Mortal Patch but BEFORE Community Pack if you use it.', '{}'::TEXT[], FALSE, to_timestamp(1464654253)) ON CONFLICT (mod_id, semver) DO NOTHING;
